'use strict';
const $=id=>document.getElementById(id),{defaults,solve,pulse}=Circuit;
const specs=[['C','Capacitance (pF)',0.001,10000,'controls'],['gK','K conductance (nS)',0,1000,'controls'],['EK','K reversal (mV)',-300,300,'controls'],['gNa','Na conductance (nS)',0,1000,'controls'],['ENa','Na reversal (mV)',-300,300,'controls'],['gCl','Cl conductance (nS)',0,1000,'controls'],['ECl','Cl reversal (mV)',-300,300,'controls'],['gL','Leak conductance (nS)',0,1000,'controls'],['EL','Leak reversal (mV)',-300,300,'controls'],['ECa','Ca reversal proxy (mV)',-300,300,'controls'],['J','Direct electron flux J (fmol/s/cell)',0,1000,'tpmet'],['eta','Uncompensated fraction η',0,1,'tpmet'],['I','Injected current (pA)',-10000,10000,'stimulus'],['f','Sinusoid frequency (Hz)',0.001,10000000,'stimulus']];
for(const [id,label,min,max,parent] of specs){const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');Object.assign(input,{id,type:'number',min,max,step:'any',value:defaults[id]});l.append(input);$(parent).append(l);input.addEventListener('input',render);}
let baseline={...defaults},current={...defaults},hypotheses=[];
function params(){const p={direction:Number($('direction').value)};for(const [id] of specs){if(!$(id).checkValidity()||$(id).value==='')throw Error('Enter valid values in all parameter fields.');p[id]=Number($(id).value);}return p;}
const fmt=n=>Math.abs(n)<0.001&&n!==0?n.toExponential(3):n.toFixed(3);
function chart(id,points){const svg=$(id),ys=points.map(x=>x[1]);let lo=Math.min(...ys),hi=Math.max(...ys);const pad=Math.max((hi-lo)*.15,1);lo-=pad;hi+=pad;const end=points.at(-1)[0],x=t=>65+470*t/end,y=v=>195-170*(v-lo)/(hi-lo);let s='<path d="M65 20V195H535" fill="none" stroke="#91a9bb"/>';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;s+=`<text x="58" y="${y(v)+4}" text-anchor="end" font-size="11">${v.toFixed(1)}</text><path d="M65 ${y(v)}H535" stroke="#e1eaf1"/>`;}s+=`<polyline points="${points.map(([t,v])=>x(t)+','+y(v)).join(' ')}" stroke="#117c96" stroke-width="2.5" fill="none"/><text x="10" y="15" font-size="12">V (mV)</text><text x="65" y="215" font-size="12">0</text><text x="535" y="215" text-anchor="end" font-size="12">${fmt(end)}</text><text x="280" y="238" font-size="12">Time (ms)</text>`;svg.innerHTML=s;}
function render(){try{current=params();const p=current,r=solve(p),b=solve(baseline);$('error').textContent='';$('export').disabled=false;const metric=[['Resting voltage',r.rest,'mV'],['TPMET net inward current',r.electronCurrent,'pA'],['Charging time τ',r.tau,'ms'],['Cutoff frequency',r.cutoff,'Hz'],['Step equilibrium',r.step,'mV'],['Sinusoidal amplitude',r.amplitude,'mV']];$('metrics').innerHTML=metric.map(([l,v,u])=>`<div class="metric">${l}<strong>${fmt(v)} <small>${u}</small></strong></div>`).join('');chart('pulse',Array.from({length:301},(_,i)=>{const t=10*r.tau*i/300;return[t,pulse(p,t,5*r.tau)];}));chart('sine',Array.from({length:301},(_,i)=>{const t=3000/p.f*i/300;return[t,r.rest+r.amplitude*Math.sin(2*Math.PI*p.f*t/1000-r.phase)];}));$('range').textContent=Math.max(Math.abs(r.rest),Math.abs(r.step),Math.abs(r.rest)+r.amplitude)>150?'Large predicted voltage: fixed conductance and constant-flux assumptions are especially unlikely to hold. Treat this as an extrapolation warning.':'All outputs are conditional on the passive circuit assumptions. No cancer outcome has been calculated.';
$('comparison').innerHTML=[['rest','Resting voltage (mV)'],['tau','Time constant (ms)'],['cutoff','Cutoff (Hz)'],['amplitude','Sinusoidal amplitude (mV)'],['calciumDrivingForce','Ca driving force ECa − Vrest (mV)']].map(([k,l])=>`<tr><td>${l}</td><td>${fmt(b[k])}</td><td>${fmt(r[k])}</td><td>${fmt(r[k]-b[k])}</td></tr>`).join('');$('sweep').innerHTML=[0,.25,.5,.75,1].map(eta=>{const q=solve({...p,eta});return`<tr><td>${eta}</td><td>${fmt(q.electronCurrent)}</td><td>${fmt(q.rest)}</td></tr>`;}).join('');
hypotheses=[{title:'Electrical coupling · quantitative prediction',prediction:`The current circuit predicts a TPMET resting-voltage shift of ${fmt(r.rest-r.ionicRest)} mV relative to zero direct electron flux, with ionic conductances fixed.`,test:'Measure electron flux and voltage in the same cell system while independently estimating charge compensation. A voltage change inconsistent with the predicted sign or magnitude falsifies this parameterized approximation.'},{title:'Cell signalling · conditional hypothesis',prediction:`Calcium driving force ECa − Vrest changes by ${fmt(r.calciumDrivingForce-b.calciumDrivingForce)} mV from baseline. Whether calcium entry changes depends on channel availability and gating.`,test:'Measure calcium and voltage together; compare voltage-clamped conditions and appropriate channel controls. No calcium response despite altered driving force challenges the proposed signalling link.'},{title:'Cancer growth or death · competing mechanisms',prediction:'A TPMET perturbation may affect redox state independently of its voltage effect. The direction of proliferation or death cannot be inferred from this circuit.',test:'Compare TPMET perturbation with an ionic perturbation matched for membrane voltage. Measure NAD(P)H/redox readouts, proliferation, live cell counts and apoptosis separately, with orthogonal perturbations and rescue controls. Similar redox and fate results would challenge a TPMET-specific effect.'},{title:'Electrical response · frequency hypothesis',prediction:`For this injected sinusoidal current, predicted voltage amplitude is ${fmt(r.amplitude)} mV at ${fmt(p.f)} Hz. Changes in C/G alter frequency filtering.`,test:'Measure impedance or current-clamp responses across frequencies and compare with the predicted amplitude and phase. Field treatments require a separate field-to-membrane coupling model; this does not predict treatment efficacy.'}];$('hypotheses').replaceChildren();for(const h of hypotheses){const d=document.createElement('article'),title=document.createElement('h3'),pr=document.createElement('p'),te=document.createElement('p');title.textContent=h.title;pr.textContent=h.prediction;te.textContent='Test / falsifier: '+h.test;te.className='muted';d.append(title,pr,te);$('hypotheses').append(d);}
}catch(e){$('error').textContent=e.message;$('export').disabled=true;$('metrics').textContent='Results unavailable until inputs are valid.';for(const id of ['comparison','sweep','hypotheses','pulse','sine'])$(id).replaceChildren();}}
$('direction').addEventListener('change',render);$('baseline').onclick=()=>{try{const candidate=params();solve(candidate);baseline={...candidate};render();}catch(e){$('error').textContent=e.message;}};$('reset').onclick=()=>{for(const [id]of specs)$(id).value=defaults[id];$('direction').value=1;baseline={...defaults};render();};$('export').onclick=()=>{const p=params(),record={model:'passive-tpmet-circuit-1.0',researchStatus:'Exploratory research tool. Default parameters are illustrative. Cancer-outcome hypotheses are unvalidated. Literature search results await screening and are not exhaustive.',documentationRevision:1,timestamp:new Date().toISOString(),parameters:p,baseline,results:solve(p),baselineResults:solve(baseline),units:{C:'pF',g:'nS',E:'mV',J:'fmol electrons/s/cell',I:'pA',f:'Hz',time:'ms'},equations:['C dV/dt = -sum(g*(V-E)) + Iapp + s*96.48533212*eta*J','Vrest=(sum(g*E)+ITPMET)/sum(g)','tau=C/sum(g)'],assumptions:'Fixed conductances and reversal potentials; prescribed direct electron flux; lumped charge compensation. Illustrative defaults, not cancer calibrated. No predicted phenotype or ROS.',provenance:$('provenance').value,hypotheses,userHypothesis:$('hypothesis-note').value,sources:['12991237','12673252','31229569','20334912','37738861'].map(pmid=>'https://pubmed.ncbi.nlm.nih.gov/'+pmid+'/')};const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='tpmet-circuit-experiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};render();
